/// <summary>
/// PaffH 12.08.22
/// </summary>
/// <param name = "_refRecIdNDXProdIdentBlockTable">RefRecId</param>
/// <param name = "_name">NDXProdIdentBlockFieldName</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXProdIdentBlockLine</returns>
public static NDXProdIdentBlockLine find(RefRecId _refRecIdNDXProdIdentBlockTable, NDXProdIdentBlockFieldName _name, boolean _forUpdate = true)
{
    NDXProdIdentBlockLine nDXProdIdentBlockLine;
    nDXProdIdentBlockLine.selectForUpdate(_forUpdate);
    select firstonly nDXProdIdentBlockLine
        where nDXProdIdentBlockLine.NDXProdIdentBlockTable == _refRecIdNDXProdIdentBlockTable
        && nDXProdIdentBlockLine.Name == _name;
    return nDXProdIdentBlockLine;
}

/// <summary>
/// PaffH 12.08.22
/// </summary>
/// <param name = "_refRecIdNDXProdIdentBlockTable">RefRecId</param>
/// <param name = "_name">NDXProdIdentBlockFieldName</param>
/// <param name = "_doInsert">boolean</param>
/// <returns>NDXProdIdentBlockLine</returns>
public static NDXProdIdentBlockLine findOrCreate(RefRecId _refRecIdNDXProdIdentBlockTable, NDXProdIdentBlockFieldName _name, boolean _doInsert = true)
{
    NDXProdIdentBlockLine nDXProdIdentBlockLine = NDXProdIdentBlockLine::find(_refRecIdNDXProdIdentBlockTable, _name, true);
    if (!nDXProdIdentBlockLine)
    {
        nDXProdIdentBlockLine.NDXProdIdentBlockTable = _refRecIdNDXProdIdentBlockTable;
        nDXProdIdentBlockLine.Name = _name;
        if (_doInsert)
        {
            nDXProdIdentBlockLine.insert();
        }
    }
    return nDXProdIdentBlockLine;
}

/// <summary>
/// PaffH 21.03.23
/// </summary>
/// <returns>boolean</returns>
public boolean checkMethod()
{
    #define.CRLF('\n')
    str             infostr;
    boolean         lDoCheck = false;
    NDXChecked     checked;
    str             strValue;

    if (this.TextType != NDXProdIdentTextType::var)
    {
        return true;
    }

    changecompany(NDXHelperDataArea::NDXItemIdPrefixEnum2DataAreaId(NDXItemIdPrefixEnum::Niedax))
    {
        InventTable inventTable = InventTable::find('1-RL 60.100');
        infostr = 'Prüfung einer statischen Methode' + #CRLF + #CRLF;
        infostr += strfmt('Klasse : [%1]', this.ClassName) + #CRLF;
        infostr += strfmt('Methode: [%1]', this.StaticMethodName) + #CRLF;
        switch (this.RetValType)
        {
            case Types::String      :
                switch (this.ParmType_Var1)
                {
                    case NDXProdIdentParmType::Artikelnummer :
                        infostr += strfmt('Parameter 1: [%1]', this.ParmType_Var1) + #CRLF;
                        infostr += strfmt('Testwert  1: [%1]', inventTable.ItemId) + #CRLF;
                        lDoCheck = true;
                        break;
                    default :
                        checked = NoYes::No;
                }
                break;
        }
        if (lDoCheck)
        {
            switch (this.RetValType)
            {
                case Types::String      :
                    str strError;
                    int classId = className2Id(this.ClassName);
                    if (!classId)
                    {
                        infostr += strFmt('Klasse: [%1] existiert nicht!', this.ClassName) + #CRLF;
                        checked = NoYes::No;
                    }
                    else
                    {
                        [strValue, strError] = NDXProdIdent::getResult(classId, this.StaticMethodName, [inventTable.ItemId]);
                        this.RetValExample = strValue;
                        checked = strError ? NoYes::No : NoYes::Yes;
                        if (strError)
                        {
                            infostr += strFmt('Fehler: [%1]', strError) + #CRLF;
                        }
                        infostr += strfmt('Ergebnis  1: [%1]', strValue) + #CRLF;
                    }
                    break;

            }
        }
        this.Checked    = checked;
        info(infostr);
    }
    return true;
}
